    33  /*
    34   * hb_hashmap_t
    35   */
    36
    37  template <typename K, typename V,
    38            K kINVALID = hb_is_pointer (K) ? 0 : hb_is_signed (K) ? hb_int_min (K) : (K) -1,
    39            V vINVALID = hb_is_pointer (V) ? 0 : hb_is_signed (V) ? hb_int_min (V) : (V) -1>
    40  struct hb_hashmap_t
    41  {
    42    HB_DELETE_COPY_ASSIGN (hb_hashmap_t);
    43    hb_hashmap_t ()  { init (); }
    44    ~hb_hashmap_t () { fini (); }
    45
    46    static_assert (hb_is_integer (K) || hb_is_pointer (K), "");
    47    static_assert (hb_is_integer (V) || hb_is_pointer (V), "");
    48
    49    /* TODO If key type is a pointer, keep hash in item_t and use to:
    50     * 1. avoid rehashing when resizing table, and
    51     * 2. compare hash before comparing keys, for speed.
    52     */
    53    struct item_t
    54    {
    55      K key;
    56      V value;
    57
    58      void clear () { key = kINVALID; value = vINVALID; }
    59
    60      bool operator == (K o) { return hb_deref (key) == hb_deref (o); }
    61      bool operator == (const item_t &o) { return *this == o.key; }
    62      bool is_unused () const    { return key == kINVALID; }
    63      bool is_tombstone () const { return key != kINVALID && value == vINVALID; }
    64      bool is_real () const { return key != kINVALID && value != vINVALID; }
    65    };
    66
    67    hb_object_header_t header;
    68    bool successful; /* Allocations successful */
    69    unsigned int population; /* Not including tombstones. */
    70    unsigned int occupancy; /* Including tombstones. */
    71    unsigned int mask;
    72    unsigned int prime;
    73    item_t *items;
    74
    75    void init_shallow ()
    76    {
    77      successful = true;
    78      population = occupancy = 0;
    79      mask = 0;
    80      prime = 0;
    81      items = nullptr;
    82    }
    83    void init ()
    84    {
    85      hb_object_init (this);
    86      init_shallow ();
    87    }
    88    void fini_shallow ()
    89    {
    90      free (items);
    91      items = nullptr;
    92      population = occupancy = 0;
    93    }
    94    void fini ()
    95    {
    96      hb_object_fini (this);
    97      fini_shallow ();
    98    }
    99
   100    void reset ()
   101    {
   102      if (unlikely (hb_object_is_immutable (this)))
   103        return;
   104      successful = true;
   105      clear ();
   106    }
   107
   108    bool in_error () const { return !successful; }
   109
   110    bool resize ()
   111    {
   112      if (unlikely (!successful)) return false;
   113
   114      unsigned int power = hb_bit_storage (population * 2 + 8);
   115      unsigned int new_size = 1u << power;
   116      item_t *new_items = (item_t *) malloc ((size_t) new_size * sizeof (item_t));
   117      if (unlikely (!new_items))
   118      {
   119        successful = false;
   120        return false;
   121      }
   122      + hb_iter (new_items, new_size)
   123      | hb_apply (&item_t::clear)
   124      ;
   125
   126      unsigned int old_size = mask + 1;
   127      item_t *old_items = items;
   128
   129      /* Switch to new, empty, array. */
   130      population = occupancy = 0;
   131      mask = new_size - 1;
   132      prime = prime_for (power);
   133      items = new_items;
   134
   135      /* Insert back old items. */
   136      if (old_items)
   137        for (unsigned int i = 0; i < old_size; i++)
   138          if (old_items[i].is_real ())
   139            set (old_items[i].key, old_items[i].value);
   140
   141      free (old_items);
   142
   143      return true;
   144    }
   145
   146    void set (K key, V value)
   147    {
   148      if (unlikely (!successful)) return;
   149      if (unlikely (key == kINVALID)) return;
   150      if ((occupancy + occupancy / 2) >= mask && !resize ()) return;
   151      unsigned int i = bucket_for (key);
   152
   153      if (value == vINVALID && items[i].key != key)
   154        return; /* Trying to delete non-existent key. */
   155
   156      if (!items[i].is_unused ())
   157      {
   158        occupancy--;
   159        if (items[i].is_tombstone ())
   160          population--;
   161      }
   162
   163      items[i].key = key;
   164      items[i].value = value;
   165
   166      occupancy++;
   167      if (!items[i].is_tombstone ())
   168        population++;
   169
   170    }
   171    V get (K key) const
   172    {
   173      if (unlikely (!items)) return vINVALID;
   174      unsigned int i = bucket_for (key);
   175      return items[i].is_real () && items[i] == key ? items[i].value : vINVALID;
   176    }
   177
   178    void del (K key) { set (key, vINVALID); }
   179
   180    /* Has interface. */
   181    static constexpr V SENTINEL = vINVALID;
   182    typedef V value_t;
   183    value_t operator [] (K k) const { return get (k); }
   184    bool has (K k) const { return (*this)[k] != SENTINEL; }
   185    /* Projection. */
   186    V operator () (K k) const { return get (k); }
   187
   188    void clear ()
   189    {
   190      if (unlikely (hb_object_is_immutable (this)))
   191        return;
   192      if (items)
   193        + hb_iter (items, mask + 1)
   194        | hb_apply (&item_t::clear)
   195        ;
   196
   197      population = occupancy = 0;
   198    }
   199
   200    bool is_empty () const { return population == 0; }
   201
   202    unsigned int get_population () const { return population; }
   203
   204    protected:
   205
   206    unsigned int bucket_for (K key) const
   207    {
   208      unsigned int i = hb_hash (key) % prime;
   209      unsigned int step = 0;
   210      unsigned int tombstone = (unsigned) -1;
   211      while (!items[i].is_unused ())
   212      {
   213        if (items[i] == key)
   214          return i;
   215        if (tombstone == (unsigned) -1 && items[i].is_tombstone ())
   216          tombstone = i;
   217        i = (i + ++step) & mask;
   218      }
   219      return tombstone == (unsigned) -1 ? i : tombstone;
   220    }

