    36  template <typename Type>
    37  struct hb_sorted_array_t;
    38
    39  template <typename Type>
    40  struct hb_array_t : hb_iter_with_fallback_t<hb_array_t<Type>, Type&>
    41  {
    42    /*
    43     * Constructors.
    44     */
    45    hb_array_t () : arrayZ (nullptr), length (0) {}
    46    hb_array_t (Type *array_, unsigned int length_) : arrayZ (array_), length (length_) {}
    47    template <unsigned int length_> hb_array_t (Type (&array_)[length_]) : arrayZ (array_), length (length_) {}
    48
    49    template <typename U,
    50              hb_enable_if (hb_is_cr_convertible_to(U, Type))>
    51    hb_array_t (const hb_array_t<U> &o) :
    52      hb_iter_with_fallback_t<hb_array_t<Type>, Type&> (),
    53      arrayZ (o.arrayZ), length (o.length) {}
    54    template <typename U,
    55              hb_enable_if (hb_is_cr_convertible_to(U, Type))>
    56    hb_array_t& operator = (const hb_array_t<U> &o)
    57    { arrayZ = o.arrayZ; length = o.length; return *this; }
    58
    59    /*
    60     * Iterator implementation.
    61     */
    62    typedef Type& __item_t__;
    63    static constexpr bool is_random_access_iterator = true;
    64    Type& __item_at__ (unsigned i) const
    65    {
    66      if (unlikely (i >= length)) return CrapOrNull (Type);
    67      return arrayZ[i];
    68    }
    69    void __forward__ (unsigned n)
    70    {
    71      if (unlikely (n > length))
    72        n = length;
    73      length -= n;
    74      arrayZ += n;
    75    }
    76    void __rewind__ (unsigned n)
    77    {
    78      if (unlikely (n > length))
    79        n = length;
    80      length -= n;
    81    }
    82    unsigned __len__ () const { return length; }
    83    bool operator != (const hb_array_t& o) const
    84    { return arrayZ != o.arrayZ || length != o.length; }
    85
    86    /* Extra operators.
    87     */
    88    Type * operator & () const { return arrayZ; }
    89    operator hb_array_t<const Type> () { return hb_array_t<const Type> (arrayZ, length); }
    90    template <typename T> operator T * () const { return arrayZ; }
    91
    92    HB_INTERNAL bool operator == (const hb_array_t &o) const;
    93    HB_INTERNAL uint32_t hash () const;
    94
    95    /*
    96     * Compare, Sort, and Search.
    97     */
    98
    99    /* Note: our compare is NOT lexicographic; it also does NOT call Type::cmp. */
   100    int cmp (const hb_array_t<Type> &a) const
   101    {
   102      if (length != a.length)
   103        return (int) a.length - (int) length;
   104      return hb_memcmp (a.arrayZ, arrayZ, get_size ());
   105    }
   106    HB_INTERNAL static int cmp (const void *pa, const void *pb)
   107    {
   108      hb_array_t<Type> *a = (hb_array_t<Type> *) pa;
   109      hb_array_t<Type> *b = (hb_array_t<Type> *) pb;
   110      return b->cmp (*a);
   111    }
