   113    template <typename T>
   114    Type *lsearch (const T &x, Type *not_found = nullptr)
   115    {
   116      unsigned int count = length;
   117      for (unsigned int i = 0; i < count; i++)
   118        if (!this->arrayZ[i].cmp (x))
   119          return &this->arrayZ[i];
   120      return not_found;
   121    }
   122    template <typename T>
   123    const Type *lsearch (const T &x, const Type *not_found = nullptr) const
   124    {
   125      unsigned int count = length;
   126      for (unsigned int i = 0; i < count; i++)
   127        if (!this->arrayZ[i].cmp (x))
   128          return &this->arrayZ[i];
   129      return not_found;
   130    }
   131
   132    hb_sorted_array_t<Type> qsort (int (*cmp_)(const void*, const void*))
   133    {
   134      if (likely (length))
   135        ::qsort (arrayZ, length, this->item_size, cmp_);
   136      return hb_sorted_array_t<Type> (*this);
   137    }
   138    hb_sorted_array_t<Type> qsort ()
   139    {
   140      if (likely (length))
   141        ::qsort (arrayZ, length, this->item_size, Type::cmp);
   142      return hb_sorted_array_t<Type> (*this);
   143    }
   144    void qsort (unsigned int start, unsigned int end)
   145    {
   146      end = MIN (end, length);
   147      assert (start <= end);
   148      if (likely (start < end))
   149        ::qsort (arrayZ + start, end - start, this->item_size, Type::cmp);
   150    }
