   152    /*
   153     * Other methods.
   154     */
   155
   156    unsigned int get_size () const { return length * this->item_size; }
   157
   158    hb_array_t<Type> sub_array (unsigned int start_offset = 0, unsigned int *seg_count = nullptr /* IN/OUT */) const
   159    {
   160      if (!start_offset && !seg_count)
   161        return *this;
   162
   163      unsigned int count = length;
   164      if (unlikely (start_offset > count))
   165        count = 0;
   166      else
   167        count -= start_offset;
   168      if (seg_count)
   169        count = *seg_count = MIN (count, *seg_count);
   170      return hb_array_t<Type> (arrayZ + start_offset, count);
   171    }
   172    hb_array_t<Type> sub_array (unsigned int start_offset, unsigned int seg_count) const
